// C documentation
//
//	/*
//	 * auto-adjust of ATH, useful for low volume
//	 * Gabriel Bouvigne 3 feb 2001
//	 *
//	 * modifies some values in
//	 *   gfp->internal_flags->ATH
//	 *   (gfc->ATH)
//	 */
func adjust_ATH(tls *libc.TLS, gfc uintptr) {
	var adj_lim_new, gr2_max, max_pow, v1 FLOAT
	var cfg, v2 uintptr
	_, _, _, _, _, _ = adj_lim_new, cfg, gr2_max, max_pow, v1, v2
	cfg = gfc + 24
	if (*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fuse_adjust == 0 {
		(*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_factor = float32(1) /* no adjustment */
		return
	}
	/* jd - 2001 mar 12, 27, jun 30 */
	/* loudness based on equal loudness curve; */
	/* use granule with maximum combined loudness */
	max_pow = *(*FLOAT)(unsafe.Pointer(gfc + 27868))
	gr2_max = *(*FLOAT)(unsafe.Pointer(gfc + 27868 + 1*8))
	if (*SessionConfig_t)(unsafe.Pointer(cfg)).Fchannels_out == int32(2) {
		max_pow = max_pow + *(*FLOAT)(unsafe.Pointer(gfc + 27868 + 1*4))
		gr2_max = gr2_max + *(*FLOAT)(unsafe.Pointer(gfc + 27868 + 1*8 + 1*4))
	} else {
		max_pow = max_pow + max_pow
		gr2_max = gr2_max + gr2_max
	}
	if (*SessionConfig_t)(unsafe.Pointer(cfg)).Fmode_gr == int32(2) {
		if max_pow > gr2_max {
			v1 = max_pow
		} else {
			v1 = gr2_max
		}
		max_pow = v1
	}
	max_pow = float32(float64(max_pow) * libc.Float64FromFloat64(0.5)) /* max_pow approaches 1.0 for full band noise */
	/* jd - 2001 mar 31, jun 30 */
	/* user tuning of ATH adjustment region */
	max_pow = max_pow * (*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Faa_sensitivity_p
	/*  adjust ATH depending on range of maximum value
	 */
	/* jd - 2001 feb27, mar12,20, jun30, jul22 */
	/* continuous curves based on approximation */
	/* to GB's original values. */
	/* For an increase in approximate loudness, */
	/* set ATH adjust to adjust_limit immediately */
	/* after a delay of one frame. */
	/* For a loudness decrease, reduce ATH adjust */
	/* towards adjust_limit gradually. */
	/* max_pow is a loudness squared or a power. */
	if float64(max_pow) > float64(0.03125) { /* ((1 - 0.000625)/ 31.98) from curve below */
		if float64((*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_factor) >= float64(1) {
			(*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_factor = float32(1)
		} else {
			/* preceding frame has lower ATH adjust; */
			/* ascend only to the preceding adjust_limit */
			/* in case there is leading low volume */
			if (*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_factor < (*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_limit {
				(*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_factor = (*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_limit
			}
		}
		(*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_limit = float32(1)
	} else { /* adjustment curve */
		/* about 32 dB maximum adjust (0.000625) */
		adj_lim_new = float32(float64(float64(31.98)*float64(max_pow)) + float64(0.000625))
		if (*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_factor >= adj_lim_new { /* descend gradually */
			v2 = (*lame_internal_flags)(unsafe.Pointer(gfc)).FATH + 8
			*(*FLOAT)(unsafe.Pointer(v2)) = FLOAT(float64(*(*FLOAT)(unsafe.Pointer(v2))) * (float64(float64(adj_lim_new)*libc.Float64FromFloat64(0.075)) + libc.Float64FromFloat64(0.925)))
			if (*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_factor < adj_lim_new { /* stop descent */
				(*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_factor = adj_lim_new
			}
		} else { /* ascend */
			if (*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_limit >= adj_lim_new {
				(*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_factor = adj_lim_new
			} else { /* preceding frame has lower ATH adjust; */
				/* ascend only to the preceding adjust_limit */
				if (*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_factor < (*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_limit {
					(*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_factor = (*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_limit
				}
			}
		}
		(*ATH_t)(unsafe.Pointer((*lame_internal_flags)(unsafe.Pointer(gfc)).FATH)).Fadjust_limit = adj_lim_new
	}
}

/***********************************************************************
 *
 *  some simple statistics
 *
 *  bitrate index 0: free bitrate -> not allowed in VBR mode
 *  : bitrates, kbps depending on MPEG version
 *  bitrate index 15: forbidden
 *
 *  mode_ext:
 *  0:  LR
 *  1:  LR-i
 *  2:  MS
 *  3:  MS-i
 *
 ***********************************************************************/

func updateStats(tls *libc.TLS, gfc uintptr) {
	var bt, ch, gr int32
	var cfg, eov uintptr
	_, _, _, _, _ = bt, cfg, ch, eov, gr
	cfg = gfc + 24
	eov = gfc + 86688
	if libc.BoolInt64(!(0 <= (*EncResult_t)(unsafe.Pointer(eov)).Fbitrate_index && (*EncResult_t)(unsafe.Pointer(eov)).Fbitrate_index < int32(16))) != 0 {
		libc.X__assert_rtn(tls, uintptr(unsafe.Pointer(&__func__13)), __ccgo_ts+1839, int32(161), __ccgo_ts+1926)
	}
	if libc.BoolInt64(!(0 <= (*EncResult_t)(unsafe.Pointer(eov)).Fmode_ext && (*EncResult_t)(unsafe.Pointer(eov)).Fmode_ext < int32(4))) != 0 {
		libc.X__assert_rtn(tls, uintptr(unsafe.Pointer(&__func__13)), __ccgo_ts+1839, int32(162), __ccgo_ts+1977)
	}
	/* count bitrate indices */
	*(*int32)(unsafe.Pointer(eov + uintptr((*EncResult_t)(unsafe.Pointer(eov)).Fbitrate_index)*20 + 4*4)) = *(*int32)(unsafe.Pointer(eov + uintptr((*EncResult_t)(unsafe.Pointer(eov)).Fbitrate_index)*20 + 4*4)) + 1
	*(*int32)(unsafe.Pointer(eov + 15*20 + 4*4)) = *(*int32)(unsafe.Pointer(eov + 15*20 + 4*4)) + 1
	/* count 'em for every mode extension in case of 2 channel encoding */
	if (*SessionConfig_t)(unsafe.Pointer(cfg)).Fchannels_out == int32(2) {
		*(*int32)(unsafe.Pointer(eov + uintptr((*EncResult_t)(unsafe.Pointer(eov)).Fbitrate_index)*20 + uintptr((*EncResult_t)(unsafe.Pointer(eov)).Fmode_ext)*4)) = *(*int32)(unsafe.Pointer(eov + uintptr((*EncResult_t)(unsafe.Pointer(eov)).Fbitrate_index)*20 + uintptr((*EncResult_t)(unsafe.Pointer(eov)).Fmode_ext)*4)) + 1
		*(*int32)(unsafe.Pointer(eov + 15*20 + uintptr((*EncResult_t)(unsafe.Pointer(eov)).Fmode_ext)*4)) = *(*int32)(unsafe.Pointer(eov + 15*20 + uintptr((*EncResult_t)(unsafe.Pointer(eov)).Fmode_ext)*4)) + 1
	}
	gr = 0
	for {
		if !(gr < (*SessionConfig_t)(unsafe.Pointer(cfg)).Fmode_gr) {
			break
		}
		ch = 0
		for {
			if !(ch < (*SessionConfig_t)(unsafe.Pointer(cfg)).Fchannels_out) {
				break
			}
			bt = (*(*gr_info)(unsafe.Pointer(gfc + 320 + uintptr(gr)*10528 + uintptr(ch)*5264))).Fblock_type
			if (*(*gr_info)(unsafe.Pointer(gfc + 320 + uintptr(gr)*10528 + uintptr(ch)*5264))).Fmixed_block_flag != 0 {
				bt = int32(4)
			}
			*(*int32)(unsafe.Pointer(eov + 320 + uintptr((*EncResult_t)(unsafe.Pointer(eov)).Fbitrate_index)*24 + uintptr(bt)*4)) = *(*int32)(unsafe.Pointer(eov + 320 + uintptr((*EncResult_t)(unsafe.Pointer(eov)).Fbitrate_index)*24 + uintptr(bt)*4)) + 1
			*(*int32)(unsafe.Pointer(eov + 320 + uintptr((*EncResult_t)(unsafe.Pointer(eov)).Fbitrate_index)*24 + 5*4)) = *(*int32)(unsafe.Pointer(eov + 320 + uintptr((*EncResult_t)(unsafe.Pointer(eov)).Fbitrate_index)*24 + 5*4)) + 1
			*(*int32)(unsafe.Pointer(eov + 320 + 15*24 + uintptr(bt)*4)) = *(*int32)(unsafe.Pointer(eov + 320 + 15*24 + uintptr(bt)*4)) + 1
			*(*int32)(unsafe.Pointer(eov + 320 + 15*24 + 5*4)) = *(*int32)(unsafe.Pointer(eov + 320 + 15*24 + 5*4)) + 1
			goto _2
		_2:
			;
			ch = ch + 1
		}
		goto _1
	_1:
		;
		gr = gr + 1
	}
}

