func optimum_samplefreq(tls *libc.TLS, lowpassfreq int32, input_samplefreq int32) (r int32) {
	var suggested_samplefreq int32
	_ = suggested_samplefreq
	/*
	 * Rules:
	 *  - if possible, sfb21 should NOT be used
	 *
	 */
	suggested_samplefreq = int32(44100)
	if input_samplefreq >= int32(48000) {
		suggested_samplefreq = int32(48000)
	} else {
		if input_samplefreq >= int32(44100) {
			suggested_samplefreq = int32(44100)
		} else {
			if input_samplefreq >= int32(32000) {
				suggested_samplefreq = int32(32000)
			} else {
				if input_samplefreq >= int32(24000) {
					suggested_samplefreq = int32(24000)
				} else {
					if input_samplefreq >= int32(22050) {
						suggested_samplefreq = int32(22050)
					} else {
						if input_samplefreq >= int32(16000) {
							suggested_samplefreq = int32(16000)
						} else {
							if input_samplefreq >= int32(12000) {
								suggested_samplefreq = int32(12000)
							} else {
								if input_samplefreq >= int32(11025) {
									suggested_samplefreq = int32(11025)
								} else {
									if input_samplefreq >= int32(8000) {
										suggested_samplefreq = int32(8000)
									}
								}
							}
						}
					}
				}
			}
		}
	}
	if lowpassfreq == -int32(1) {
		return suggested_samplefreq
	}
	if lowpassfreq <= int32(15960) {
		suggested_samplefreq = int32(44100)
	}
	if lowpassfreq <= int32(15250) {
		suggested_samplefreq = int32(32000)
	}
	if lowpassfreq <= int32(11220) {
		suggested_samplefreq = int32(24000)
	}
	if lowpassfreq <= int32(9970) {
		suggested_samplefreq = int32(22050)
	}
	if lowpassfreq <= int32(7230) {
		suggested_samplefreq = int32(16000)
	}
	if lowpassfreq <= int32(5420) {
		suggested_samplefreq = int32(12000)
	}
	if lowpassfreq <= int32(4510) {
		suggested_samplefreq = int32(11025)
	}
	if lowpassfreq <= int32(3970) {
		suggested_samplefreq = int32(8000)
	}
	if input_samplefreq < suggested_samplefreq {
		/* choose a valid MPEG sample frequency above the input sample frequency
		   to avoid SFB21/12 bitrate bloat
		   rh 061115
		*/
		if input_samplefreq > int32(44100) {
			return int32(48000)
		}
		if input_samplefreq > int32(32000) {
			return int32(44100)
		}
		if input_samplefreq > int32(24000) {
			return int32(32000)
		}
		if input_samplefreq > int32(22050) {
			return int32(24000)
		}
		if input_samplefreq > int32(16000) {
			return int32(22050)
		}
		if input_samplefreq > int32(12000) {
			return int32(16000)
		}
		if input_samplefreq > int32(11025) {
			return int32(12000)
		}
		if input_samplefreq > int32(8000) {
			return int32(11025)
		}
		return int32(8000)
	}
	return suggested_samplefreq
}

