				temp2 = float32(libc.Xfabs(tls, float64(*(*FLOAT)(unsafe.Pointer(cod_info + uintptr(j)*4)))) - float64(pow43[*(*int32)(unsafe.Pointer(ix + uintptr(j)*4))]*step))
