// C documentation
//
//	/*
//	 * LAME's estimate of the total number of frames to be encoded.
//	 * Only valid if calling program set num_samples.
//	 */
func lame_get_totalframes(tls *libc.TLS, gfp uintptr) (r int32) {
	var cfg, gfc uintptr
	var end_padding, pcm_samples_per_frame, pcm_samples_to_encode uint64
	var frames int32
	var frames_f, resampled_samples_to_encode float64
	_, _, _, _, _, _, _, _ = cfg, end_padding, frames, frames_f, gfc, pcm_samples_per_frame, pcm_samples_to_encode, resampled_samples_to_encode
	if is_lame_global_flags_valid(tls, gfp) != 0 {
		gfc = (*lame_global_flags)(unsafe.Pointer(gfp)).Finternal_flags
		if is_lame_internal_flags_valid(tls, gfc) != 0 {
			cfg = gfc + 24
			pcm_samples_per_frame = libc.Uint64FromInt32(int32(576) * (*SessionConfig_t)(unsafe.Pointer(cfg)).Fmode_gr)
			pcm_samples_to_encode = (*lame_global_flags)(unsafe.Pointer(gfp)).Fnum_samples
			end_padding = uint64(0)
			frames = 0
			if pcm_samples_to_encode == libc.Uint64FromUint64(0)-libc.Uint64FromUint64(1) {
				return 0
			} /* unknown */
			/* estimate based on user set num_samples: */
			if (*SessionConfig_t)(unsafe.Pointer(cfg)).Fsamplerate_in != (*SessionConfig_t)(unsafe.Pointer(cfg)).Fsamplerate_out {
				/* resampling, estimate new samples_to_encode */
				resampled_samples_to_encode = float64(0)
				frames_f = float64(0)
				if (*SessionConfig_t)(unsafe.Pointer(cfg)).Fsamplerate_in > 0 {
					resampled_samples_to_encode = float64(pcm_samples_to_encode)
					resampled_samples_to_encode = resampled_samples_to_encode * float64((*SessionConfig_t)(unsafe.Pointer(cfg)).Fsamplerate_out)
					resampled_samples_to_encode = resampled_samples_to_encode / float64((*SessionConfig_t)(unsafe.Pointer(cfg)).Fsamplerate_in)
				}
				if resampled_samples_to_encode <= float64(0) {
					return 0
				} /* unlikely to happen, so what, no estimate! */
				frames_f = libc.Xfloor(tls, resampled_samples_to_encode/float64(pcm_samples_per_frame))
				if frames_f >= float64(libc.Int32FromInt32(__INT_MAX__)-libc.Int32FromInt32(2)) {
					return 0
				} /* overflow, happens eventually, no estimate! */
				frames = int32(frames_f)
				resampled_samples_to_encode = resampled_samples_to_encode - float64(libc.Uint64FromInt32(frames)*pcm_samples_per_frame)
				pcm_samples_to_encode = uint64(libc.Xceil(tls, resampled_samples_to_encode))
			} else {
				frames = libc.Int32FromUint64(pcm_samples_to_encode / pcm_samples_per_frame)
				pcm_samples_to_encode = pcm_samples_to_encode - libc.Uint64FromInt32(frames)*pcm_samples_per_frame
			}
			pcm_samples_to_encode = pcm_samples_to_encode + uint64(576)
			end_padding = pcm_samples_per_frame - pcm_samples_to_encode%pcm_samples_per_frame
			if end_padding < uint64(576) {
				end_padding = end_padding + pcm_samples_per_frame
			}
			pcm_samples_to_encode = pcm_samples_to_encode + end_padding
			frames = libc.Int32FromUint64(uint64(frames) + pcm_samples_to_encode/pcm_samples_per_frame)
			/* check to see if we underestimated totalframes */
			/*    if (totalframes < gfp->frameNum) */
			/*        totalframes = gfp->frameNum; */
			return frames
		}
	}
	return 0
}

func lame_set_preset(tls *libc.TLS, gfp uintptr, preset int32) (r int32) {
	if is_lame_global_flags_valid(tls, gfp) != 0 {
		(*lame_global_flags)(unsafe.Pointer(gfp)).Fpreset = preset
		return apply_preset(tls, gfp, preset, int32(1))
	}
	return -int32(1)
}

func lame_set_asm_optimizations(tls *libc.TLS, gfp uintptr, optim int32, mode int32) (r int32) {
	var v1 int32
	_ = v1
	if is_lame_global_flags_valid(tls, gfp) != 0 {
		if mode == int32(1) {
			v1 = int32(1)
		} else {
			v1 = 0
		}
		mode = v1
		switch optim {
		case int32(MMX):
			(*lame_global_flags)(unsafe.Pointer(gfp)).Fasm_optimizations.Fmmx = mode
			return optim
		case int32(AMD_3DNOW):
			(*lame_global_flags)(unsafe.Pointer(gfp)).Fasm_optimizations.Famd3dnow = mode
			return optim
		case int32(SSE):
			(*lame_global_flags)(unsafe.Pointer(gfp)).Fasm_optimizations.Fsse = mode
			return optim
		default:
			return optim
		}
	}
	return -int32(1)
}

