func calc_maximum_input_samples_for_buffer_size(tls *libc.TLS, gfc uintptr, buffer_size size_t) (r int32) {
	var bpf, frames_per_buffer, input_samples_per_buffer, kbps, pad, pcm_samples_per_frame int32
	var cfg uintptr
	var ratio float64
	_, _, _, _, _, _, _, _ = bpf, cfg, frames_per_buffer, input_samples_per_buffer, kbps, pad, pcm_samples_per_frame, ratio
	cfg = gfc + 24
	pcm_samples_per_frame = int32(576) * (*SessionConfig_t)(unsafe.Pointer(cfg)).Fmode_gr
	frames_per_buffer = 0
	input_samples_per_buffer = 0
	kbps = int32(320)
	if (*SessionConfig_t)(unsafe.Pointer(cfg)).Fsamplerate_out < int32(16000) {
		kbps = int32(64)
	} else {
		if (*SessionConfig_t)(unsafe.Pointer(cfg)).Fsamplerate_out < int32(32000) {
			kbps = int32(160)
		} else {
			kbps = int32(320)
		}
	}
	if (*SessionConfig_t)(unsafe.Pointer(cfg)).Ffree_format != 0 {
		kbps = (*SessionConfig_t)(unsafe.Pointer(cfg)).Favg_bitrate
	} else {
		if (*SessionConfig_t)(unsafe.Pointer(cfg)).Fvbr == int32(vbr_off) {
			kbps = (*SessionConfig_t)(unsafe.Pointer(cfg)).Favg_bitrate
		}
	}
	pad = int32(1)
	bpf = ((*SessionConfig_t)(unsafe.Pointer(cfg)).Fversion+libc.Int32FromInt32(1))*libc.Int32FromInt32(72000)*kbps/(*SessionConfig_t)(unsafe.Pointer(cfg)).Fsamplerate_out + pad
	frames_per_buffer = libc.Int32FromUint64(buffer_size / libc.Uint64FromInt32(bpf))
	ratio = float64((*SessionConfig_t)(unsafe.Pointer(cfg)).Fsamplerate_in) / float64((*SessionConfig_t)(unsafe.Pointer(cfg)).Fsamplerate_out)
	input_samples_per_buffer = int32(float64(pcm_samples_per_frame*frames_per_buffer) * ratio)
	return input_samples_per_buffer
}

func lame_get_maximum_number_of_samples(tls *libc.TLS, gfp lame_t, buffer_size size_t) (r int32) {
	var gfc uintptr
	_ = gfc
	if is_lame_global_flags_valid(tls, gfp) != 0 {
		gfc = (*lame_global_flags)(unsafe.Pointer(gfp)).Finternal_flags
		if is_lame_internal_flags_valid(tls, gfc) != 0 {
			return calc_maximum_input_samples_for_buffer_size(tls, gfc, buffer_size)
		}
	}
	return int32(LAME_GENERICERROR)
}

