/*
 * 0: MPEG-2 LSF
 * 1: MPEG-1
 * 2: MPEG-2.5 LSF FhG extention                  (1995-07-11 shn)
 */

type MPEG_t = int32

const MPEG_2 = 0
const MPEG_1 = 1
const MPEG_25 = 2

func lame_get_bitrate(tls *libc.TLS, mpeg_version int32, table_index int32) (r int32) {
	if 0 <= mpeg_version && mpeg_version <= int32(2) {
		if 0 <= table_index && table_index <= int32(15) {
			return *(*int32)(unsafe.Pointer(uintptr(unsafe.Pointer(&bitrate_table)) + uintptr(mpeg_version)*64 + uintptr(table_index)*4))
		}
	}
	return -int32(1)
}

func lame_get_samplerate(tls *libc.TLS, mpeg_version int32, table_index int32) (r int32) {
	if 0 <= mpeg_version && mpeg_version <= int32(2) {
		if 0 <= table_index && table_index <= int32(3) {
			return *(*int32)(unsafe.Pointer(uintptr(unsafe.Pointer(&samplerate_table)) + uintptr(mpeg_version)*16 + uintptr(table_index)*4))
		}
	}
	return -int32(1)
}

