		if *(*int32)(unsafe.Pointer(uintptr(unsafe.Pointer(&bitrate_table)) + uintptr(version)*64 + uintptr(i)*4)) > 0 {
			if *(*int32)(unsafe.Pointer(uintptr(unsafe.Pointer(&bitrate_table)) + uintptr(version)*64 + uintptr(i)*4)) == bRate {
				return i
			}
		}
